// Generated by Cypress Author on 2026-11-26.
// Regrouper le scénario de retrait d'un produit depuis la liste d'inventaire.
describe('Swag Labs cart', () => {
    // Se connecter avant le test avec la commande partagée.
    beforeEach(() => {
        // Ouvrir une session utilisateur standard sur l'inventaire.
        cy.login();
    });

    // Fermer la session après le test avec la commande partagée.
    afterEach(() => {
        // Déconnecter l'utilisateur après les vérifications.
        cy.logout();
    });

    // Définir le scénario de retrait d'un produit depuis la liste.
    it('retire un produit depuis la liste et met à jour les contrôles du panier', () => {
        // Ajouter le Sauce Labs Backpack afin de pouvoir le retirer.
        cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();
        // Vérifier que le badge indique un produit avant le retrait.
        cy.get('[data-test="shopping-cart-badge"]').should('be.visible').and('have.text', '1');

        // Retirer le Sauce Labs Backpack depuis la page Inventory.
        cy.get('[data-test="remove-sauce-labs-backpack"]').click();

        // Vérifier que le bouton redevient Add to cart.
        cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').should('be.visible').and('have.text', 'Add to cart');
        // Vérifier que le badge disparaît lorsque le panier est vide.
        cy.get('[data-test="shopping-cart-badge"]').should('not.exist');
    });
});
